record.field:
picking = env['stock.picking'].browse(record.res_id).exists()

action_result = picking.button_validate()

if (
    isinstance(action_result, dict)
    and action_result.get('res_model') == 'stock.backorder.confirmation'
):
    wizard_model = env[
        'stock.backorder.confirmation'
    ].with_context(
        action_result.get('context') or {}
    )

    wizard_values = wizard_model.default_get([
        'pick_ids',
        'show_transfers',
        'backorder_confirmation_line_ids',
    ])
    wizard = wizard_model.create(wizard_values)
    wizard.process()
